<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\DriverService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('CARRIER_DRIVER_CREATE');$errors=[];$values=$_POST?:['identity_type'=>'NATIONAL_ID','identity_country'=>'TZ','licence_country'=>'TZ','medical_result'=>'FIT'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$result=DriverService::create($_POST,(int)Auth::user()['id']);$_SESSION['driver_setup_link']=Url::to('auth/setup-password.php?token='.urlencode($result['token']));$_SESSION['driver_setup_expires']=$result['expires_at'];header('Location: '.Url::to('carrier/drivers/view.php?id='.$result['driver_id'].'&created=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}catch(Throwable$e){@file_put_contents(BASE_PATH.'/storage/logs/phase6c.log','['.date('c').'] '.$e->getMessage().PHP_EOL,FILE_APPEND|LOCK_EX);$errors[]='Driver profile could not be created. Check the local error log.';}}$pageTitle='Create Driver';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Create Driver</h1><p>The verified Carrier approves the profile for McCollins Operations verification.</p></div><span class="badge">Phase 6C</span></div><div class="notice">A one-time 24-hour password-setup link will be shown once. Deliver it securely to the Driver. File uploads are deferred to Phase 10.</div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><?php require BASE_PATH.'/app/Views/drivers/form.php';?><div class="actions"><button class="button">Create and submit Driver</button><a class="button secondary" href="<?=h(Url::to('carrier/drivers/index.php'))?>">Cancel</a></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
